-- Canonical aliases and descriptions from docs/data-model.md. No row, permission or constraint changes.
BEGIN;
SET LOCAL search_path = pg_catalog;
SET LOCAL lock_timeout = '10s';
COMMENT ON COLUMN catalog.actor.id IS 'Internal ID. Immutable internal identity, separate from the public catalog identifier and source identifiers. Alias (DE): Interne ID. Canonical: Actor.id.';
COMMENT ON COLUMN catalog.actor.identifier IS 'ID. Stable and unique within its kind. Child identifiers distinguish records across owners. Alias (DE): Kennung. Canonical: Actor.identifier.';
COMMENT ON COLUMN catalog.actor.row_version IS 'Edit revision. Automatically maintained edit revision; initially 1 and advanced on stored changes, including owned edits. Separate from catalog definition version. Alias (DE): Bearbeitungsrevision. Canonical: Actor.rowVersion.';
COMMENT ON COLUMN catalog.actor.created_on IS 'Created. Date the catalog record was created; unknown historical dates remain unknown. Alias (DE): Erstellt am. Canonical: Actor.createdOn.';
COMMENT ON COLUMN catalog.actor.modified_on IS 'Last modified. Date the catalog record last changed; not before createdOn. History and edit revision establish order. Alias (DE): Zuletzt geändert am. Canonical: Actor.modifiedOn.';
COMMENT ON COLUMN catalog.actor.name_de IS 'Name (DE). German name; at least one language is required. Not an identifier. Alias (DE): Name (DE). Canonical: Actor.name_de.';
COMMENT ON COLUMN catalog.actor.name_it IS 'Name (IT). Italian name; at least one language is required. Not an identifier. Alias (DE): Name (IT). Canonical: Actor.name_it.';
COMMENT ON COLUMN catalog.actor.name_fr IS 'Name (FR). French name; at least one language is required. Not an identifier. Alias (DE): Name (FR). Canonical: Actor.name_fr.';
COMMENT ON COLUMN catalog.actor.name_en IS 'Name (EN). English name; at least one language is required. Not an identifier. Alias (DE): Name (EN). Canonical: Actor.name_en.';
COMMENT ON COLUMN catalog.actor.description_de IS 'Description (DE). German. Definition; preserve documented wording. Alias (DE): Beschreibung (DE). Canonical: Actor.description_de.';
COMMENT ON COLUMN catalog.actor.description_it IS 'Description (IT). Italian. Definition; preserve documented wording. Alias (DE): Beschreibung (IT). Canonical: Actor.description_it.';
COMMENT ON COLUMN catalog.actor.description_fr IS 'Description (FR). French. Definition; preserve documented wording. Alias (DE): Beschreibung (FR). Canonical: Actor.description_fr.';
COMMENT ON COLUMN catalog.actor.description_en IS 'Description (EN). English. Definition; preserve documented wording. Alias (DE): Beschreibung (EN). Canonical: Actor.description_en.';
COMMENT ON COLUMN catalog.actor.comment IS 'Comment. Catalog note in its authored language; publicly readable. No translation variants, fallback or parent inheritance. Alias (DE): Kommentar. Canonical: Actor.comment.';
COMMENT ON COLUMN catalog.actor.actor_type IS 'Actor type. `person`, `organisation`. Alias (DE): Akteurstyp. Canonical: Actor.actorType.';
COMMENT ON COLUMN catalog.actor.website_url IS 'Website. Official website or directory entry. Do not fabricate URLs from names. Alias (DE): Website. Canonical: Actor.websiteUrl.';
COMMENT ON COLUMN catalog.actor.is_archived IS 'Archived. Defaults to false. Hides the entry from normal browsing while retaining identity, references and history; independent of status/verification. Alias (DE): Archiviert. Canonical: Actor.isArchived.';
COMMENT ON COLUMN catalog.actor.edited_at IS 'Last edit timestamp. Server time of the latest app/REST edit; unknown for earlier imports. Separate from source freshness, definition version and historical dates. Alias (DE): Zeitpunkt der letzten Bearbeitung. Canonical: Actor.editedAt.';
COMMENT ON COLUMN catalog.business_attribute.id IS 'Internal ID. Immutable internal identity, separate from the public catalog identifier and source identifiers. Alias (DE): Interne ID. Canonical: BusinessAttribute.id.';
COMMENT ON COLUMN catalog.business_attribute.identifier IS 'ID. Stable and unique within its kind. Child identifiers distinguish records across owners. Alias (DE): Kennung. Canonical: BusinessAttribute.identifier.';
COMMENT ON COLUMN catalog.business_attribute.row_version IS 'Edit revision. Automatically maintained edit revision; initially 1 and advanced on stored changes, including owned edits. Separate from catalog definition version. Alias (DE): Bearbeitungsrevision. Canonical: BusinessAttribute.rowVersion.';
COMMENT ON COLUMN catalog.business_attribute.created_on IS 'Created. Date the catalog record was created; unknown historical dates remain unknown. Do not copy a parent date as a child assertion. Alias (DE): Erstellt am. Canonical: BusinessAttribute.createdOn.';
COMMENT ON COLUMN catalog.business_attribute.modified_on IS 'Last modified. Date the catalog record last changed; not before createdOn. History and edit revision establish order. Do not copy a parent date as a child assertion. Alias (DE): Zuletzt geändert am. Canonical: BusinessAttribute.modifiedOn.';
COMMENT ON COLUMN catalog.business_attribute.name_de IS 'Name (DE). German name; at least one language is required. Not an identifier. Alias (DE): Name (DE). Canonical: BusinessAttribute.name_de.';
COMMENT ON COLUMN catalog.business_attribute.name_it IS 'Name (IT). Italian name; at least one language is required. Not an identifier. Alias (DE): Name (IT). Canonical: BusinessAttribute.name_it.';
COMMENT ON COLUMN catalog.business_attribute.name_fr IS 'Name (FR). French name; at least one language is required. Not an identifier. Alias (DE): Name (FR). Canonical: BusinessAttribute.name_fr.';
COMMENT ON COLUMN catalog.business_attribute.name_en IS 'Name (EN). English name; at least one language is required. Not an identifier. Alias (DE): Name (EN). Canonical: BusinessAttribute.name_en.';
COMMENT ON COLUMN catalog.business_attribute.description_de IS 'Description (DE). German. Definition; preserve documented wording. At least one language value in this property family is required before status becomes valid. Alias (DE): Beschreibung (DE). Canonical: BusinessAttribute.description_de.';
COMMENT ON COLUMN catalog.business_attribute.description_it IS 'Description (IT). Italian. Definition; preserve documented wording. At least one language value in this property family is required before status becomes valid. Alias (DE): Beschreibung (IT). Canonical: BusinessAttribute.description_it.';
COMMENT ON COLUMN catalog.business_attribute.description_fr IS 'Description (FR). French. Definition; preserve documented wording. At least one language value in this property family is required before status becomes valid. Alias (DE): Beschreibung (FR). Canonical: BusinessAttribute.description_fr.';
COMMENT ON COLUMN catalog.business_attribute.description_en IS 'Description (EN). English. Definition; preserve documented wording. At least one language value in this property family is required before status becomes valid. Alias (DE): Beschreibung (EN). Canonical: BusinessAttribute.description_en.';
COMMENT ON COLUMN catalog.business_attribute.comment IS 'Comment. Catalog note in its authored language; publicly readable. No translation variants, fallback or parent inheritance. Alias (DE): Kommentar. Canonical: BusinessAttribute.comment.';
COMMENT ON COLUMN catalog.business_attribute.documentation_links IS 'More information. Curated supporting links; deduplicate identical URL/purpose pairs. Alias (DE): Weitere Informationen. Canonical: BusinessAttribute.documentationLinks.';
COMMENT ON COLUMN catalog.business_attribute.status IS 'Status. `draft`, `valid`, `retired`; new records default to draft. Status changes are manual and audited; source publication alone does not establish the correctness of local interpretations. Alias (DE): Status. Canonical: BusinessAttribute.status.';
COMMENT ON COLUMN catalog.business_attribute.version IS 'Version. Catalog definition version, if managed; paired with versionDate. Separate from source editions, serviceVersion and the technical rowVersion. Alias (DE): Version. Canonical: BusinessAttribute.version.';
COMMENT ON COLUMN catalog.business_attribute.version_date IS 'Version date. Date this catalog definition version was issued. Required for a newly assigned/changed version; absent without version. Preserve unknown legacy dates. Not an import, last-edit or service-release date. Alias (DE): Versionsdatum. Canonical: BusinessAttribute.versionDate.';
COMMENT ON COLUMN catalog.business_attribute.responsible_organisation IS 'Responsible organisation. Inline organisation; no Actor required. Apply the documented parent fallback only when this whole value is absent. Alias (DE): Verantwortliche Organisation. Canonical: BusinessAttribute.responsibleOrganisation.';
COMMENT ON COLUMN catalog.business_attribute.data_owner_id IS 'Data owner. Accountable person/organisation. One optional Actor; apply only the documented parent fallback. Alias (DE): Dateneigner. Canonical: BusinessAttribute.dataOwnerId.';
COMMENT ON COLUMN catalog.business_attribute.data_steward_id IS 'Data steward. Person/organisation maintaining meaning and metadata. One optional Actor; apply only the documented parent fallback. Alias (DE): Datenverwalter. Canonical: BusinessAttribute.dataStewardId.';
COMMENT ON COLUMN catalog.business_attribute.contact_actor_id IS 'Contact. Optional managed contact with name and website/contact page. External links may stay in responsibleOrganisation. Apply only the documented parent fallback. Alias (DE): Kontakt. Canonical: BusinessAttribute.contactActorId.';
COMMENT ON COLUMN catalog.business_attribute.classification IS 'Classification. `public`, `internal`, `confidential`, `secret`. Classification of the described information, separate from technical access. Alias (DE): Klassifizierung. Canonical: BusinessAttribute.classification.';
COMMENT ON COLUMN catalog.business_attribute.contains_personal_data IS 'Personal data. Whether the described data contains personal data. Listing a catalog contact does not establish this for the underlying dataset. Alias (DE): Personendaten. Canonical: BusinessAttribute.containsPersonalData.';
COMMENT ON COLUMN catalog.business_attribute.business_object_id IS 'Business object. Owning business definition. Alias (DE): Geschäftsobjekt. Canonical: BusinessAttribute.businessObjectId.';
COMMENT ON COLUMN catalog.business_attribute.semantic_name IS 'Semantic name. Stable English name, unique within the owner, for example `constructionYear`. Independent of localized labels. Alias (DE): Semantischer Name. Canonical: BusinessAttribute.semanticName.';
COMMENT ON COLUMN catalog.business_attribute.value_specification IS 'Value specification. Descriptive value type/format/unit only; required before status becomes valid. Validation rules come from qualityRequirementIds, not inline bounds or conditions. Alias (DE): Wertespezifikation. Canonical: BusinessAttribute.valueSpecification.';
COMMENT ON COLUMN catalog.business_attribute.is_identifier IS 'Business identifier. Participation in business identification. Does not establish a physical key or global uniqueness. Alias (DE): Fachlicher Identifikator. Canonical: BusinessAttribute.isIdentifier.';
COMMENT ON COLUMN catalog.business_attribute.code_list_id IS 'Code list. Reviewed vocabulary; similar source wording is insufficient evidence. Alias (DE): Werteliste. Canonical: BusinessAttribute.codeListId.';
COMMENT ON COLUMN catalog.business_attribute.edited_at IS 'Last edit timestamp. Server time of the latest app/REST edit; unknown for earlier imports. Separate from source freshness, definition version and historical dates. Alias (DE): Zeitpunkt der letzten Bearbeitung. Canonical: BusinessAttribute.editedAt.';
COMMENT ON COLUMN catalog.business_attribute.sort_order IS 'Row order. Display order within the owner, from 0 through 2147483647 (SQL integer); defaults to 0. Reordering preserves row identity. Ties are permitted. Alias (DE): Zeilenreihenfolge. Canonical: BusinessAttribute.sortOrder.';
COMMENT ON COLUMN catalog.business_attribute.is_archived IS 'Archived. Defaults to false. Hides the entry from normal browsing while retaining identity, references and history; independent of status/verification. Alias (DE): Archiviert. Canonical: BusinessAttribute.isArchived.';
COMMENT ON COLUMN catalog.business_attribute.system_of_record_id IS 'System of record. Explicit authoritative-system override. Null inherits the owning BusinessObject designation; clearing restores inheritance. Effective values remain derived. Stored as system_of_record_id; existing System required. See [system of record](#system-of-record). Alias (DE): Führendes System. Canonical: BusinessAttribute.systemOfRecordId.';
COMMENT ON COLUMN catalog.business_attribute_quality_requirement.business_attribute_id IS 'Data quality requirements. Reusable quality rules assigned to this attribute/field; no duplicates or per-assignment overrides. Resolve each referenced rule''s definition and status; no automatic parent-status cascade. Business requirements stay solution-neutral; field rules describe additional source expectations. Alias (DE): Datenqualitätsanforderungen. Canonical: BusinessAttribute.qualityRequirementIds.';
COMMENT ON COLUMN catalog.business_attribute_quality_requirement.quality_requirement_id IS 'Data quality requirements. Reusable quality rules assigned to this attribute/field; no duplicates or per-assignment overrides. Resolve each referenced rule''s definition and status; no automatic parent-status cascade. Business requirements stay solution-neutral; field rules describe additional source expectations. Alias (DE): Datenqualitätsanforderungen. Canonical: BusinessAttribute.qualityRequirementIds.';
